2. 
3. function Read-TaskStore {
4.     param([Parameter(Mandatory)][string]$Path)
5. 
6.     if (-not (Test-Path -LiteralPath $Path)) {
7.         return @()
8.     }
9. 
10.     $content = Get-Content -LiteralPath $Path -Raw
11.     if ([string]::IsNullOrWhiteSpace($content)) {
12.         return @()
13.     }
14. 
15.     $parsed = ConvertFrom-Json -InputObject $content
16.     return @($parsed)
17. }
18. 
19. function Write-TaskStore {
20.     param(
21.         [Parameter(Mandatory)][string]$Path,
22.         [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Tasks
23.     )
24. 
25.     $parent = Split-Path -Parent $Path
26.     if ($parent -and -not (Test-Path -LiteralPath $parent)) {
27.         New-Item -ItemType Directory -Path $parent -Force | Out-Null
28.     }
29. 
30.     $temporary = "$Path.$PID.tmp"
31.     $json = ConvertTo-Json -InputObject @($Tasks) -Depth 8
32.     [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
33.     Move-Item -LiteralPath $temporary -Destination $Path -Force
34. }
35. 
36. function Read-TaskForgeConfig {
37.     param([Parameter(Mandatory)][string]$Path)
38. 
39.     $config = [ordered]@{
40.         dataFile = $null
41.         defaultJson = $false
42.     }
43.     if (-not (Test-Path -LiteralPath $Path)) {
44.         return $config
45.     }
46. 
47.     $content = Get-Content -LiteralPath $Path -Raw
48.     if ([string]::IsNullOrWhiteSpace($content)) {
49.         throw "Configuration file is empty: $Path"
50.     }
51. 
52.     $parsed = ConvertFrom-Json -InputObject $content
53.     foreach ($property in $parsed.PSObject.Properties) {
54.         if ($property.Name -notin @('dataFile', 'defaultJson')) {
55.             throw "Unknown configuration key: $($property.Name)"
56.         }
57.         $config[$property.Name] = $property.Value
58.     }
59. 
60.     if ($null -ne $config.dataFile -and
61.         ($config.dataFile -isnot [string] -or [string]::IsNullOrWhiteSpace($config.dataFile))) {
62.         throw 'Configuration key dataFile must be a non-empty string.'
63.     }
64.     if ($config.defaultJson -isnot [bool]) {
65.         throw 'Configuration key defaultJson must be a boolean.'
66.     }
67. 
68.     return $config
69. }
70. 
71. function Write-TaskForgeConfig {
72.     param(
73.         [Parameter(Mandatory)][string]$Path,
74.         [Parameter(Mandatory)][System.Collections.IDictionary]$Config
75.     )
76. 
77.     $parent = Split-Path -Parent $Path
78.     if ($parent -and -not (Test-Path -LiteralPath $parent)) {
79.         New-Item -ItemType Directory -Path $parent -Force | Out-Null
80.     }
81. 
82.     $temporary = Join-Path $parent ".$([System.IO.Path]::GetFileName($Path)).$PID.$([guid]::NewGuid()).tmp"
83.     try {
84.         $json = ConvertTo-Json -InputObject $Config -Depth 4
85.         [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
86.         Move-Item -LiteralPath $temporary -Destination $Path -Force
87.     }
88.     finally {
89.         if (Test-Path -LiteralPath $temporary) {
90.             Remove-Item -LiteralPath $temporary -Force
91.         }
92.     }
93. }
94. 
95. function Resolve-TaskForgePath {
96.     param(
97.         [Parameter(Mandatory)][string]$Path,
98.         [Parameter(Mandatory)][string]$ConfigFile
99.     )
100. 
101.     if ([System.IO.Path]::IsPathFullyQualified($Path)) {
102.         return [System.IO.Path]::GetFullPath($Path)
103.     }
104. 
105.     $configDirectory = Split-Path -Parent $ConfigFile
106.     return [System.IO.Path]::GetFullPath((Join-Path $configDirectory $Path))
107. }
108. 
109. function ConvertTo-TaskForgeBoolean {
110.     param(
111.         [Parameter(Mandatory)]$Value,
112.         [Parameter(Mandatory)][string]$Name
113.     )
114. 
115.     if ($Value -is [bool]) {
116.         return [bool]$Value
117.     }
118. 
119.     $parsed = $false
120.     if (-not [bool]::TryParse([string]$Value, [ref]$parsed)) {
121.         throw "$Name must be true or false."
122.     }
123.     return $parsed
124. }
125. 
126. function ConvertFrom-TaskForgeArguments {
127.     param([AllowEmptyCollection()][string[]]$Arguments)
128. 
129.     $options = [ordered]@{}
130.     for ($index = 0; $index -lt $Arguments.Count; $index++) {
131.         $token = $Arguments[$index]
132.         if (-not $token.StartsWith('--')) {
133.             throw "Unexpected argument: $token"
134.         }
135. 
136.         $name = $token.Substring(2)
137.         if ([string]::IsNullOrWhiteSpace($name)) {
138.             throw 'Option name cannot be empty.'
139.         }
140.         if ($options.Contains($name)) {
141.             throw "Duplicate option: --$name"
142.         }
143. 
144.         if (($index + 1) -lt $Arguments.Count -and -not $Arguments[$index + 1].StartsWith('--')) {
145.             $options[$name] = $Arguments[++$index]
146.         }
147.         else {
148.             $options[$name] = $true
149.         }
150.     }
151. 
152.     return $options
153. }
154. 
155. function Get-RequiredOption {
156.     param(
157.         [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
158.         [Parameter(Mandatory)][string]$Name
159.     )
160. 
161.     if (-not $Options.Contains($Name) -or $Options[$Name] -is [bool] -or
162.         [string]::IsNullOrWhiteSpace([string]$Options[$Name])) {
163.         throw "Missing required option: --$Name"
164.     }
165.     return [string]$Options[$Name]
166. }
167. 
168. function Assert-KnownOptions {
169.     param(
170.         [Parameter(Mandatory)][System.Collections.IDictionary]$Options,
171.         [Parameter(Mandatory)][AllowEmptyCollection()][string[]]$Allowed
172.     )
173. 
174.     foreach ($name in $Options.Keys) {
175.         if ($name -notin $Allowed) {
176.             throw "Unknown option: --$name"
177.         }
178.     }
179. }
